                outside[r][c] = True
                q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 0 and not outside[nr][nc]:
                outside[nr][nc] = True
                q.append((nr, nc))

    inside = [[grid[r][c] == 0 and not outside[r][c] for c in range(w)] for r in range(h)]
    if not any(any(row) for row in inside):
        return [row[:] for row in grid]

    # Components of the outline bordering enclosed areas are candidates for the outer halo.
    relevant = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if inside[r][c]:
                for dr in (-1, 0, 1):
                    for dc in (-1, 0, 1):
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < h and 0 <= nc < w and grid[nr][nc] == 1:
                            relevant[nr][nc] = True
    # Propagate relevance through each 4-connected 1 component.
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or seen[r][c]:
                continue
